\item if \(\varphi=(\psi\circ\chi)\), then
\[
\operatorname{Sub}(\varphi)=\{\varphi\}\cup\operatorname{Sub}(\psi)\cup\operatorname{Sub}(\chi).
\]
\end{enumerate}

