support_blocks.body_tex:
\[
\begin{aligned}
&\text{Let } (P,S,1) \text{ be a Peano system.}\\
&\forall A \subseteq P\;
\Bigl(A \neq \varnothing \Longrightarrow
\exists m \in A\;\forall a \in A\;(m \le a)\Bigr).
\end{aligned}
\]

\[
\operatorname{WellOrderingPrinciple}
\;\coloneqq\;
\forall A\;\bigl((A \subseteq P \land \exists a\,(a \in A))
\Rightarrow \exists m\,(m \in A \land \forall a\,(a \in A \Rightarrow m \le a))\bigr).
\]

\[
\begin{aligned}
&\text{Let } (P,S,1) \text{ be a Peano system.}\\
&\exists A \subseteq P\;
\Bigl(A \neq \varnothing \land
\forall m \in A\;\exists a \in A\;(a < m)\Bigr).
\end{aligned}
\]

\begin{description}
  \item[Exposition.]
  The well-ordering principle would fail if some nonempty subset of $P$ had
  no least element. That means for every candidate minimum, a strictly smaller
  element of the subset exists, producing an infinite strictly descending
  chain in $P$. Induction rules this out.
  \item[No least element.]
  \[
  \neg\operatorname{WellOrderingPrinciple}.
  \]
  \[
  \neg\operatorname{WellOrderingPrinciple}
  \Longleftrightarrow
  \exists A \subseteq P\;
  \Bigl(\underbrace{A \neq \varnothing}_{\text{nonempty}}
  \land
  \underbrace{\forall m \in A\;\exists a \in A\;(a < m)}_{\text{no least element}}
  \Bigr).
  \]
\end{description}

