\[
\begin{aligned}
&\text{Let } (P,S,1) \text{ be a Peano system and let } A \subseteq P.\\
&A \text{ is successor-closed}
\Longleftrightarrow
\forall n \in P\;(n \in A \Longrightarrow S(n) \in A).
\end{aligned}
\]

\[
\begin{aligned}
&\text{Let } (P,S,1) \text{ be a Peano system and let } A \subseteq P.\\
&A \text{ is not successor-closed}
\Longleftrightarrow
\exists n \in P\;(n \in A \land S(n) \notin A).
\end{aligned}
\]

\begin{description}
  \item[Exposition.]
  A subset fails to be successor-closed exactly when it contains some element
  of $P$ but fails to contain that element's successor.
  \item[Quantified failure.]
  \[
  \begin{aligned}
  A \text{ is not successor-closed}
  \Longleftrightarrow
  \exists n \in P\;\underbrace{(n \in A \land S(n) \notin A)}_{\text{closure fails at } n}.
  \end{aligned}
  \]
\end{description}

