\;\Longleftrightarrow\;
&\;\exists \varepsilon > 0 \;\forall N \in \mathbb{N} \;\exists n \ge N\\
&\quad\bigl(x_n \notin I_\varepsilon(L)\bigr).
\end{aligned}
\]

\begin{description}
  \item[Exposition.]
\[
\underbrace{\exists \varepsilon > 0}_{\text{a fixed centered interval}}
\;\underbrace{\forall N \in \mathbb{N}}_{\text{no tail suffices}}
\;\underbrace{\exists n \ge N}_{\text{terms escape infinitely often}}
\;\underbrace{x_n \notin I_\varepsilon(L)}_{\text{outside every candidate interval}}.
\]
The sequence fails to converge to $L$ precisely when some centered interval
of $L$ contains only finitely many terms: infinitely many terms lie
permanently outside it.
\end{description}

