support_blocks.body_tex:
\begin{description}
  \item[Exposition.]
Each component hypothesis is indispensable: without closedness (for instance $f(x)=1/x$ on $(0,1]$) continuity does not prevent divergence near the missing endpoint; without bounded domain (for example $f(x)=x$ on $[0,\infty)$) linear growth forces unbounded values; without continuity (take $f(0)=0$ and $f(x)=1/x$ for $x\in(0,1]$) the discontinuity at $0$ again creates arbitrarily large magnitudes.
\end{description}

\begin{description}
  \item[Exposition.]
\[
\begin{aligned}
\neg\bigl[\operatorname{IsClosedInterval}(a,b) \land \operatorname{Bounded}([a,b]) \land \operatorname{IsContinuous}(f,[a,b])\bigr]
&=
\underbrace{\neg\operatorname{IsClosedInterval}(a,b)}_{\text{missing endpoint}}
\lor
\underbrace{\neg\operatorname{Bounded}([a,b])}_{\text{unbounded domain}}
\lor
\underbrace{\neg\operatorname{IsContinuous}(f,[a,b])}_{\text{discontinuity}}.
\end{aligned}
\]
\end{description}

