&\neg\bigl[(x_{*} \in A) \land \operatorname{LeastElement}(f(x_{*}), f(A))\bigr]
= \underbrace{(x_{*} \notin A)}_{\text{external point}}
\lor
\underbrace{\bigl(\exists x \in A\; (f(x_{*}) > f(x))\bigr)}_{\text{better value}}.
\end{aligned}
\]
\end{description}

