\ \underbrace{\forall \delta>0}_{\text{every centered interval}}
\ \underbrace{\exists x\in A}_{\text{nearby witness}}
:\
|x-c|<\delta \land |f(x)-f(c)| \ge \varepsilon_0.
\]
\end{description}

