x\notin D(f)\land \omega(f;x)>0 & \text{(Type II)},\\[4pt]
\omega(f;x)>0\land \forall n\in\mathbb{N}\; \omega(f;x)<\tfrac1n & \text{(Type III)}.
\end{cases}
\]
\end{description}

